script:
frappe.ui.form.on('Customer', {
	refresh(frm) {
		if (!frm.doc.custom_date_de_naissance) {
			return;
		}
		const age = moment().diff(frm.doc.custom_date_de_naissance, 'years');
		frm.set_value('custom_age', age, false, true);
	},
})

frappe.ui.form.on('Payment Entry', {
	party(frm) {
		if (frm.doc.party_type !== 'Customer' || !frm.doc.party) {
			return;
		}

		frappe.call({
			method: 'frappe.client.get_value',
			args: {
				doctype: 'Customer',
				fieldname: 'customer_primary_contact',
				filters: { name: frm.doc.party },
			},
			callback(r) {
				if (r.message?.customer_primary_contact) {
					frm.set_value('contact_person', r.message.customer_primary_contact);
				}
			},
		});
	},
});

frappe.ui.form.on('Expense Claim', {
	cost_center(frm) {
		(frm.doc.expenses || []).forEach((expense) => {
			expense.cost_center = frm.doc.cost_center;
		});
		frm.refresh_field('expenses');
	},
	project(frm) {
		(frm.doc.expenses || []).forEach((expense) => {
			expense.project = frm.doc.project;
		});
		frm.refresh_field('expenses');
	},
});

frappe.ui.form.on('Expense Claim Detail', {
	expenses_add(frm) {
		const row = frm.doc.expenses[frm.doc.expenses.length - 1];
		row.cost_center = frm.doc.cost_center;
		row.project = frm.doc.project;
		frm.refresh_field('expenses');
	},
});

const DOCTYPE_SALES_INVOICE = 'Sales Invoice';
const DOCTYPE_CUSTOMER = 'Customer';
const DOCTYPE_CUSTOMER_GROUP = 'Customer Group';
const FIELD_CUSTOMER_GROUP = 'customer_group';
const FIELD_COST_CENTER = 'cost_center';
const FIELD_CUSTOMER_GROUP_COST_CENTER = 'custom_centre_de_cout';

frappe.ui.form.on(DOCTYPE_SALES_INVOICE, {
	customer(frm) {
		if (!frm.doc.customer) {
			return;
		}

		frappe.call({
			method: 'frappe.client.get_value',
			args: {
				doctype: DOCTYPE_CUSTOMER,
				filters: { name: frm.doc.customer },
				fieldname: FIELD_CUSTOMER_GROUP,
			},
			callback(r) {
				const customer_group = r.message?.[FIELD_CUSTOMER_GROUP];
				if (!customer_group) {
					return;
				}

				frappe.call({
					method: 'frappe.client.get_value',
					args: {
						doctype: DOCTYPE_CUSTOMER_GROUP,
						filters: { name: customer_group },
						fieldname: FIELD_CUSTOMER_GROUP_COST_CENTER,
					},
					callback(res) {
						const cost_center = res.message?.[FIELD_CUSTOMER_GROUP_COST_CENTER];
						if (cost_center && frm.doc[FIELD_COST_CENTER] !== cost_center) {
							frm.set_value(FIELD_COST_CENTER, cost_center);
						}
					},
				});
			},
		});
	},
});
